      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Interactive Velocity Cursor Image Trail</title>\n  <style>\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  width: 100%;\n  height: 100%;\n  background: #09090b;\n  color: #fafafa;\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", sans-serif;\n  overflow: hidden;\n  user-select: none;\n}\n\n.trail-stage {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  overflow: hidden;\n  background:\n    radial-gradient(circle at 50% 50%, rgba(168, 85, 247, 0.12), transparent 65%),\n    #09090b;\n  cursor: crosshair;\n}\n\n.trail-grid-bg {\n  position: absolute;\n  inset: 0;\n  background-image:\n    linear-gradient(to right, rgba(255,255,255,0.04) 1px, transparent 1px),\n    linear-gradient(to bottom, rgba(255,255,255,0.04) 1px, transparent 1px);\n  background-size: 48px 48px;\n  pointer-events: none;\n}\n\n.trail-content {\n  position: relative;\n  z-index: 5000;\n  pointer-events: none;\n  padding: 24px;\n}\n\n.trail-eyebrow {\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: 0.2em;\n  text-transform: uppercase;\n  color: #a855f7;\n  margin-bottom: 12px;\n}\n\n.trail-heading {\n  font-size: clamp(32px, 5.5vw, 68px);\n  font-weight: 800;\n  letter-spacing: -0.04em;\n  line-height: 1.02;\n  mix-blend-mode: difference;\n}\n\n.trail-sub {\n  margin-top: 14px;\n  font-size: 14px;\n  color: rgba(250, 250, 250, 0.6);\n}\n\n.image-trail {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 210px;\n  height: 150px;\n  border-radius: 10px;\n  overflow: hidden;\n  pointer-events: none;\n  opacity: 0;\n  border: 1px solid rgba(255, 255, 255, 0.22);\n  box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.75);\n  will-change: transform, opacity;\n  display: flex;\n  flex-direction: column;\n  justify-content: flex-end;\n  padding: 12px;\n}\n\n.image-trail span {\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: rgba(255, 255, 255, 0.92);\n  text-shadow: 0 2px 8px rgba(0,0,0,0.6);\n}\n\n</style>\n</head>\n<body>\n  <div class=\"trail-stage\" id=\"main-container\">\n    <div class=\"trail-grid-bg\"></div>\n    <div class=\"trail-content\">\n      <div class=\"trail-eyebrow\">Gallery Play // Interactive Motion</div>\n      <h1 class=\"trail-heading\">MOVE YOUR CURSOR<br/>ACROSS THE CANVAS</h1>\n      <p class=\"trail-sub\">Velocity-driven momentum cards spawn and drift along your pointer trajectory</p>\n    </div>\n  </div>\n  <script>\n/**\n * Interactive Velocity Cursor Image Trail\n * Extracted from carousel-gallery-play/app.js (initImageTrail)\n */\n(function () {\n  const container = document.getElementById('main-container');\n  if (!container) return;\n\n  const TRAIL_CARDS = [\n    { label: '01 // AJAX 125', bg: 'linear-gradient(135deg, #dc2626, #7f1d1d)' },\n    { label: '02 // RED DEVILS', bg: 'linear-gradient(135deg, #ea580c, #431407)' },\n    { label: '03 // COMO 1907', bg: 'linear-gradient(135deg, #0284c7, #0c4a6e)' },\n    { label: '04 // ADIDAS X TZOLIS', bg: 'linear-gradient(135deg, #10b981, #064e3b)' },\n    { label: '05 // HOKA SPEED', bg: 'linear-gradient(135deg, #3b82f6, #172554)' },\n    { label: '06 // LIMBXL CAMPAIGN', bg: 'linear-gradient(135deg, #a855f7, #3b0764)' },\n    { label: '07 // BNXT ARENA', bg: 'linear-gradient(135deg, #6366f1, #1e1b4b)' },\n    { label: '08 // ROYAL ANTWERP', bg: 'linear-gradient(135deg, #f43f5e, #4c0519)' },\n    { label: '09 // AL QADSIAH', bg: 'linear-gradient(135deg, #eab308, #422006)' },\n    { label: '10 // DAZN STUDIO', bg: 'linear-gradient(135deg, #14b8a6, #042f2e)' }\n  ];\n\n  const images = TRAIL_CARDS.map((card) => {\n    const el = document.createElement('div');\n    el.className = 'image-trail';\n    el.style.background = card.bg;\n    el.innerHTML = `<span>${card.label}</span>`;\n    container.appendChild(el);\n    return el;\n  });\n\n  let currentIndex = 0;\n  let zCounter = 10;\n  let lastPos = null;\n  const minDistance = 80;\n\n  function getLocalCoords(e) {\n    const rect = container.getBoundingClientRect();\n    return {\n      x: e.clientX - rect.left,\n      y: e.clientY - rect.top\n    };\n  }\n\n  function spawnTrailImage(x, y, dx, dy) {\n    const img = images[currentIndex];\n    currentIndex = (currentIndex + 1) % images.length;\n\n    const offsetX = 105;\n    const offsetY = 75;\n    const driftFactor = 0.65;\n    const rot = (Math.random() * 16 - 8).toFixed(2);\n\n    img.getAnimations().forEach((anim) => anim.cancel());\n    img.style.zIndex = String(zCounter++);\n\n    img.animate(\n      [\n        {\n          transform: `translate3d(${x - offsetX}px, ${y - offsetY}px, 0) scale(0.85) rotate(${rot}deg)`,\n          opacity: 1,\n          offset: 0\n        },\n        {\n          transform: `translate3d(${x - offsetX + dx * driftFactor}px, ${y - offsetY + dy * driftFactor}px, 0) scale(1.02) rotate(${rot}deg)`,\n          opacity: 1,\n          offset: 0.48\n        },\n        {\n          transform: `translate3d(${x - offsetX + dx * driftFactor * 1.2}px, ${y - offsetY + dy * driftFactor * 1.2 + 16}px, 0) scale(0.4) rotate(${rot}deg)`,\n          opacity: 0,\n          offset: 1\n        }\n      ],\n      {\n        duration: 1050,\n        easing: 'cubic-bezier(0.22, 1, 0.36, 1)',\n        fill: 'forwards'\n      }\n    );\n  }\n\n  container.addEventListener(\n    'pointermove',\n    (e) => {\n      const pos = getLocalCoords(e);\n      if (!lastPos) {\n        lastPos = pos;\n        spawnTrailImage(pos.x, pos.y, 18, -12);\n        return;\n      }\n      const dx = pos.x - lastPos.x;\n      const dy = pos.y - lastPos.y;\n      const dist = Math.hypot(dx, dy);\n\n      if (dist >= minDistance) {\n        spawnTrailImage(pos.x, pos.y, dx, dy);\n        lastPos = pos;\n      }\n    },\n    { passive: true }\n  );\n})();\n\n</script>\n</body>\n</html>\n",
