      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Custom Glassmorphic & Magnetic Target Cursor</title>\n  <style>\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  width: 100%;\n  height: 100%;\n  background: #09090b;\n  color: #fafafa;\n  font-family: -apple-system, BlinkMacSystemFont, \"Inter\", sans-serif;\n  overflow: hidden;\n}\n\n.mag-stage {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 28px;\n  padding: 24px;\n  background: radial-gradient(circle at 50% 50%, rgba(255, 55, 0, 0.1), transparent 65%), #09090b;\n}\n\n.mag-cards {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 18px;\n  width: 100%;\n  max-width: 820px;\n}\n\n.mag-zone {\n  position: relative;\n  padding: 32px 24px;\n  border-radius: 16px;\n  background: rgba(255, 255, 255, 0.03);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  text-align: center;\n  cursor: none;\n  transition: border-color 0.25s, background 0.25s;\n}\n\n.mag-zone:hover {\n  border-color: rgba(255, 55, 0, 0.6);\n  background: rgba(255, 55, 0, 0.06);\n}\n\n.mag-zone h3 {\n  font-size: 18px;\n  font-weight: 700;\n  margin-bottom: 6px;\n}\n\n.mag-zone p {\n  font-size: 13px;\n  color: rgba(250, 250, 250, 0.55);\n}\n\n.mag-buttons {\n  display: flex;\n  gap: 16px;\n  flex-wrap: wrap;\n}\n\n.mag-btn {\n  appearance: none;\n  padding: 14px 28px;\n  border-radius: 999px;\n  border: 1px solid rgba(255, 255, 255, 0.18);\n  background: #18181b;\n  color: #fafafa;\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  cursor: pointer;\n  transition: background 0.2s, border-color 0.2s;\n  will-change: transform;\n}\n\n.mag-btn:hover {\n  background: #ff3700;\n  border-color: #ff3700;\n}\n\n.custom-cursor {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 18px;\n  height: 18px;\n  margin-left: -9px;\n  margin-top: -9px;\n  border-radius: 50%;\n  background: rgba(255, 55, 0, 0.9);\n  color: #ffffff;\n  pointer-events: none;\n  z-index: 9999;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: 0.1em;\n  transition: width 0.28s cubic-bezier(0.22, 1, 0.36, 1),\n              height 0.28s cubic-bezier(0.22, 1, 0.36, 1),\n              margin 0.28s cubic-bezier(0.22, 1, 0.36, 1),\n              background 0.25s ease;\n  backdrop-filter: blur(8px);\n  box-shadow: 0 10px 28px rgba(255, 55, 0, 0.4);\n}\n\n.custom-cursor span {\n  opacity: 0;\n  transform: scale(0.6);\n  transition: opacity 0.2s ease, transform 0.2s ease;\n}\n\n.custom-cursor.is-active {\n  width: 88px;\n  height: 88px;\n  margin-left: -44px;\n  margin-top: -44px;\n  background: rgba(255, 55, 0, 0.88);\n}\n\n.custom-cursor.is-active span {\n  opacity: 1;\n  transform: scale(1);\n}\n\n</style>\n</head>\n<body>\n  <div class=\"mag-stage\">\n    <div class=\"mag-cards\">\n      <div class=\"mag-zone\" data-cursor-zone=\"PLAY REEL\">\n        <h3>Showreel 2026</h3>\n        <p>Hover to morph cursor into PLAY REEL</p>\n      </div>\n      <div class=\"mag-zone\" data-cursor-zone=\"EXPLORE\">\n        <h3>3D Case Studies</h3>\n        <p>Hover to morph cursor into EXPLORE</p>\n      </div>\n      <div class=\"mag-zone\" data-cursor-zone=\"DRAG 360°\">\n        <h3>Interactive Stage</h3>\n        <p>Hover to morph cursor into DRAG 360°</p>\n      </div>\n    </div>\n\n    <div class=\"mag-buttons\">\n      <button type=\"button\" class=\"mag-btn\" data-magnetic>Magnetic Action</button>\n      <button type=\"button\" class=\"mag-btn\" data-magnetic>Start Project ↗</button>\n      <button type=\"button\" class=\"mag-btn\" data-magnetic>Download Kit</button>\n    </div>\n  </div>\n\n  <div class=\"custom-cursor\" id=\"custom-cursor\"><span id=\"cursor-label\">PLAY</span></div>\n  <script>\n/**\n * Custom Glassmorphic & Magnetic Target Cursor\n * Extracted & enhanced from carousel-gallery-play/app.js (initCustomCursor)\n */\n(function () {\n  const cursor = document.getElementById('custom-cursor');\n  const labelEl = document.getElementById('cursor-label');\n  const zones = document.querySelectorAll('[data-cursor-zone]');\n  const magBtns = document.querySelectorAll('[data-magnetic]');\n\n  if (!cursor) return;\n\n  let mouseX = window.innerWidth / 2;\n  let mouseY = window.innerHeight / 2;\n  let curX = mouseX;\n  let curY = mouseY;\n\n  window.addEventListener(\n    'pointermove',\n    (e) => {\n      mouseX = e.clientX;\n      mouseY = e.clientY;\n    },\n    { passive: true }\n  );\n\n  zones.forEach((zone) => {\n    zone.addEventListener('pointerenter', () => {\n      if (labelEl) labelEl.textContent = zone.getAttribute('data-cursor-zone') || 'VIEW';\n      cursor.classList.add('is-active');\n    });\n    zone.addEventListener('pointerleave', () => {\n      cursor.classList.remove('is-active');\n    });\n  });\n\n  magBtns.forEach((btn) => {\n    btn.addEventListener('pointermove', (e) => {\n      const r = btn.getBoundingClientRect();\n      const dx = e.clientX - (r.left + r.width / 2);\n      const dy = e.clientY - (r.top + r.height / 2);\n      btn.style.transform = `translate3d(${(dx * 0.32).toFixed(1)}px, ${(dy * 0.32).toFixed(1)}px, 0)`;\n    });\n    btn.addEventListener('pointerleave', () => {\n      btn.style.transform = 'translate3d(0, 0, 0)';\n    });\n  });\n\n  function render() {\n    requestAnimationFrame(render);\n    curX += (mouseX - curX) * 0.18;\n    curY += (mouseY - curY) * 0.18;\n    cursor.style.transform = `translate3d(${curX.toFixed(1)}px, ${curY.toFixed(1)}px, 0)`;\n  }\n\n  requestAnimationFrame(render);\n})();\n\n</script>\n</body>\n</html>\n",
      "html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Custom Glassmorphic & Magnetic Target Cursor</title>\n  <link rel=\"stylesheet\" href=\"style.css\" />\n</head>\n<body>\n  <div class=\"mag-stage\">\n    <div class=\"mag-cards\">\n      <div class=\"mag-zone\" data-cursor-zone=\"PLAY REEL\">\n        <h3>Showreel 2026</h3>\n        <p>Hover to morph cursor into PLAY REEL</p>\n      </div>\n      <div class=\"mag-zone\" data-cursor-zone=\"EXPLORE\">\n        <h3>3D Case Studies</h3>\n        <p>Hover to morph cursor into EXPLORE</p>\n      </div>\n      <div class=\"mag-zone\" data-cursor-zone=\"DRAG 360°\">\n        <h3>Interactive Stage</h3>\n        <p>Hover to morph cursor into DRAG 360°</p>\n      </div>\n    </div>\n\n    <div class=\"mag-buttons\">\n      <button type=\"button\" class=\"mag-btn\" data-magnetic>Magnetic Action</button>\n      <button type=\"button\" class=\"mag-btn\" data-magnetic>Start Project ↗</button>\n      <button type=\"button\" class=\"mag-btn\" data-magnetic>Download Kit</button>\n    </div>\n  </div>\n\n  <div class=\"custom-cursor\" id=\"custom-cursor\"><span id=\"cursor-label\">PLAY</span></div>\n  <script src=\"script.js\"></script>\n</body>\n</html>\n",
