      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Split-Screen Curtain Entrance</title>\n  <style>\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody, html {\n  width: 100%;\n  height: 100%;\n  background: #0d0d0f;\n  color: #f5f2eb;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  overflow: hidden;\n}\n\n.curtain-stage {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n}\n\n.underlay-hero {\n  text-align: center;\n  max-width: 680px;\n  padding: 32px;\n  z-index: 1;\n  transition: transform 0.8s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.8s ease;\n}\n\n.eyebrow {\n  font-size: 11px;\n  letter-spacing: 0.24em;\n  text-transform: uppercase;\n  color: #a8a29e;\n  margin-bottom: 18px;\n}\n\n.hero-headline {\n  font-size: clamp(2rem, 4.5vw, 3.8rem);\n  font-weight: 400;\n  line-height: 1.08;\n  letter-spacing: -0.03em;\n  margin-bottom: 28px;\n}\n\n.hero-headline em {\n  font-family: Georgia, 'Times New Roman', serif;\n  font-style: italic;\n  color: #e6ccb2;\n}\n\n.controls {\n  display: inline-flex;\n  align-items: center;\n  gap: 16px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  padding: 10px 18px;\n  border-radius: 999px;\n}\n\n.replay-btn {\n  background: #f5f2eb;\n  color: #0d0d0f;\n  border: none;\n  padding: 8px 16px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.replay-btn:hover {\n  background: #e6ccb2;\n}\n\n#splitScrubber {\n  accent-color: #e6ccb2;\n  cursor: pointer;\n}\n\n.curtain-half {\n  position: absolute;\n  left: 0;\n  width: 100%;\n  height: 50%;\n  background: #f4f1ea;\n  color: #141413;\n  z-index: 5;\n  overflow: hidden;\n  will-change: transform;\n  transition: transform 1.15s cubic-bezier(0.76, 0, 0.24, 1);\n}\n\n.curtain-top {\n  top: 0;\n  border-bottom: 1px solid rgba(20, 20, 19, 0.12);\n}\n\n.curtain-bottom {\n  bottom: 0;\n}\n\n.monogram-wrap {\n  position: absolute;\n  left: 0;\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.curtain-top .monogram-wrap {\n  top: 0;\n}\n\n.curtain-bottom .monogram-wrap {\n  bottom: 0;\n}\n\n.monogram-text {\n  font-size: clamp(3.2rem, 11vw, 8.5rem);\n  font-weight: 800;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n}\n\n</style>\n</head>\n<body>\n  <div class=\"curtain-stage\" id=\"curtainStage\">\n    <div class=\"underlay-hero\">\n      <p class=\"eyebrow\">REPRESENTING GLOBAL VISUAL VOICES</p>\n      <h1 class=\"hero-headline\">Curated <em>Visionaries</em> &amp; Spatial Direction</h1>\n      <div class=\"controls\">\n        <button class=\"replay-btn\" id=\"replayBtn\" type=\"button\">Replay Split Entrance</button>\n        <input type=\"range\" id=\"splitScrubber\" min=\"0\" max=\"100\" value=\"100\" aria-label=\"Scrub split progress\" />\n      </div>\n    </div>\n\n    <div class=\"curtain-half curtain-top\" id=\"curtainTop\">\n      <div class=\"monogram-wrap\">\n        <span class=\"monogram-text\">VIVIENNE</span>\n      </div>\n    </div>\n\n    <div class=\"curtain-half curtain-bottom\" id=\"curtainBottom\">\n      <div class=\"monogram-wrap\">\n        <span class=\"monogram-text\">VIVIENNE</span>\n      </div>\n    </div>\n  </div>\n  <script>\n(function () {\n  const curtainTop = document.getElementById('curtainTop');\n  const curtainBottom = document.getElementById('curtainBottom');\n  const replayBtn = document.getElementById('replayBtn');\n  const scrubber = document.getElementById('splitScrubber');\n\n  function applySplit(progressPct) {\n    const p = Math.max(0, Math.min(100, Number(progressPct)));\n    curtainTop.style.transform = `translate3d(0, -${p}%, 0)`;\n    curtainBottom.style.transform = `translate3d(0, ${p}%, 0)`;\n  }\n\n  function playEntrance() {\n    curtainTop.style.transition = 'none';\n    curtainBottom.style.transition = 'none';\n    scrubber.value = '0';\n    applySplit(0);\n\n    requestAnimationFrame(() => {\n      requestAnimationFrame(() => {\n        curtainTop.style.transition = 'transform 1.2s cubic-bezier(0.76, 0, 0.24, 1)';\n        curtainBottom.style.transition = 'transform 1.2s cubic-bezier(0.76, 0, 0.24, 1)';\n        scrubber.value = '100';\n        applySplit(100);\n      });\n    });\n  }\n\n  replayBtn.addEventListener('click', playEntrance);\n  scrubber.addEventListener('input', (e) => {\n    curtainTop.style.transition = 'none';\n    curtainBottom.style.transition = 'none';\n    applySplit(e.target.value);\n  });\n\n  setTimeout(playEntrance, 220);\n})();\n\n</script>\n</body>\n</html>\n",
