      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Full-Screen Parallax Footer Reveal</title>\n  <style>\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody, html {\n  width: 100%;\n  height: 100%;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  overflow: hidden;\n}\n\n.viv-footer {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  background: #141413;\n  color: #f4f1ea;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  padding: 28px 40px;\n  transition: background-color 0.65s cubic-bezier(0.16, 1, 0.3, 1);\n  overflow: hidden;\n}\n\n.footer-top-meta,\n.footer-bottom-meta {\n  display: flex;\n  justify-content: space-between;\n  font-size: 11px;\n  letter-spacing: 0.18em;\n  text-transform: uppercase;\n  color: rgba(244, 241, 234, 0.55);\n  z-index: 3;\n}\n\n.footer-nav {\n  display: flex;\n  flex-direction: column;\n  z-index: 3;\n}\n\n.footer-link {\n  display: grid;\n  grid-template-columns: 48px 1fr auto;\n  align-items: baseline;\n  padding: 18px 0;\n  border-top: 1px solid rgba(244, 241, 234, 0.14);\n  color: #f4f1ea;\n  text-decoration: none;\n  transition: padding-left 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.35s ease;\n}\n\n.footer-link:last-child {\n  border-bottom: 1px solid rgba(244, 241, 234, 0.14);\n}\n\n.footer-nav:hover .footer-link {\n  opacity: 0.38;\n}\n\n.footer-nav .footer-link:hover {\n  opacity: 1;\n  padding-left: 18px;\n}\n\n.link-index {\n  font-size: 11px;\n  font-family: monospace;\n  color: rgba(244, 241, 234, 0.5);\n}\n\n.link-label {\n  font-size: clamp(1.85rem, 4.2vw, 3.4rem);\n  font-weight: 400;\n  letter-spacing: -0.03em;\n}\n\n.link-label em {\n  font-family: Georgia, serif;\n  font-style: italic;\n}\n\n.link-arrow {\n  font-size: 24px;\n}\n\n.floating-card {\n  position: fixed;\n  top: 0;\n  left: 0;\n  width: 240px;\n  padding: 12px;\n  background: rgba(255, 255, 255, 0.08);\n  backdrop-filter: blur(16px);\n  border: 1px solid rgba(255, 255, 255, 0.18);\n  border-radius: 8px;\n  pointer-events: none;\n  opacity: 0;\n  transform: translate3d(-50%, -50%, 0) scale(0.86);\n  transition: opacity 0.3s ease;\n  z-index: 2;\n}\n\n.floating-card.is-visible {\n  opacity: 1;\n}\n\n.floating-art {\n  width: 100%;\n  height: 170px;\n  border-radius: 4px;\n  margin-bottom: 10px;\n  background: radial-gradient(circle at 30% 30%, #eab676, #1a1423);\n}\n\n.floating-caption {\n  font-size: 11px;\n  letter-spacing: 0.06em;\n  color: #f4f1ea;\n}\n\n</style>\n</head>\n<body>\n  <footer class=\"viv-footer\" id=\"vivFooter\">\n    <div class=\"footer-top-meta\">\n      <span>PARIS &bull; NEW YORK &bull; MILAN</span>\n      <span>HOVER LINKS TO PREVIEW STUDIOS</span>\n    </div>\n\n    <nav class=\"footer-nav\" id=\"footerNav\">\n      <a href=\"#paris\" class=\"footer-link\" data-bg=\"#1a1423\" data-accent=\"#eab676\" data-city=\"24 Rue du Sentier, 75002 Paris\">\n        <span class=\"link-index\">01</span>\n        <span class=\"link-label\">Paris <em>Headquarters</em></span>\n        <span class=\"link-arrow\">&nearr;</span>\n      </a>\n      <a href=\"#newyork\" class=\"footer-link\" data-bg=\"#0f2027\" data-accent=\"#7bdff2\" data-city=\"450 Broadway, SoHo NY 10013\">\n        <span class=\"link-index\">02</span>\n        <span class=\"link-label\">New York <em>Representation</em></span>\n        <span class=\"link-arrow\">&nearr;</span>\n      </a>\n      <a href=\"#milan\" class=\"footer-link\" data-bg=\"#2b1911\" data-accent=\"#f4a261\" data-city=\"Via Solferino 18, 20121 Milano\">\n        <span class=\"link-index\">03</span>\n        <span class=\"link-label\">Milan <em>Syndication</em></span>\n        <span class=\"link-arrow\">&nearr;</span>\n      </a>\n      <a href=\"#archive\" class=\"footer-link\" data-bg=\"#132a13\" data-accent=\"#ecf39e\" data-city=\"Private Monograph &amp; Print Vault\">\n        <span class=\"link-index\">04</span>\n        <span class=\"link-label\">Monograph <em>Editions</em></span>\n        <span class=\"link-arrow\">&nearr;</span>\n      </a>\n    </nav>\n\n    <div class=\"floating-card\" id=\"floatingCard\">\n      <div class=\"floating-art\" id=\"floatingArt\"></div>\n      <div class=\"floating-caption\" id=\"floatingCaption\">Paris Studio</div>\n    </div>\n\n    <div class=\"footer-bottom-meta\">\n      <span>&copy; 2026 VIVMGMT SYNDICATION</span>\n      <span>BACK TO TOP &uarr;</span>\n    </div>\n  </footer>\n  <script>\n(function () {\n  const footer = document.getElementById('vivFooter');\n  const links = document.querySelectorAll('.footer-link');\n  const card = document.getElementById('floatingCard');\n  const art = document.getElementById('floatingArt');\n  const caption = document.getElementById('floatingCaption');\n\n  let mouseX = window.innerWidth * 0.65;\n  let mouseY = window.innerHeight * 0.5;\n  let cardX = mouseX;\n  let cardY = mouseY;\n\n  window.addEventListener('mousemove', (e) => {\n    mouseX = e.clientX;\n    mouseY = e.clientY;\n  });\n\n  links.forEach((link) => {\n    link.addEventListener('mouseenter', () => {\n      const bg = link.getAttribute('data-bg');\n      const accent = link.getAttribute('data-accent');\n      const city = link.getAttribute('data-city');\n      footer.style.backgroundColor = bg;\n      art.style.background = `radial-gradient(circle at 35% 30%, ${accent}, ${bg} 80%)`;\n      caption.textContent = city;\n      card.classList.add('is-visible');\n    });\n\n    link.addEventListener('mouseleave', () => {\n      card.classList.remove('is-visible');\n      footer.style.backgroundColor = '#141413';\n    });\n\n    link.addEventListener('click', (e) => e.preventDefault());\n  });\n\n  function animate() {\n    cardX += (mouseX - cardX) * 0.12;\n    cardY += (mouseY - cardY) * 0.12;\n    const vx = (mouseX - cardX) * 0.08;\n    card.style.transform = `translate3d(${cardX.toFixed(1)}px, ${cardY.toFixed(1)}px, 0) translate(-50%, -50%) rotate(${vx.toFixed(2)}deg)`;\n    requestAnimationFrame(animate);\n  }\n  requestAnimationFrame(animate);\n})();\n\n</script>\n</body>\n</html>\n",
