      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Morphing Burger &amp; Staggered Overlay Menu</title>\n  <style>\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody, html {\n  width: 100%;\n  height: 100%;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  overflow: hidden;\n}\n\n.nav-demo-shell {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  background: #f4f1ea;\n  color: #141413;\n}\n\n.topbar {\n  position: relative;\n  z-index: 30;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 24px 36px;\n}\n\n.brand {\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0.24em;\n  transition: color 0.4s ease;\n}\n\n.nav-demo-shell.is-open .brand {\n  color: #f4f1ea;\n}\n\n.burger-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 12px;\n  background: transparent;\n  border: 1px solid currentColor;\n  padding: 9px 16px;\n  border-radius: 999px;\n  color: inherit;\n  cursor: pointer;\n  font-size: 11px;\n  letter-spacing: 0.16em;\n  transition: color 0.4s ease, border-color 0.4s ease;\n}\n\n.nav-demo-shell.is-open .burger-btn {\n  color: #f4f1ea;\n}\n\n.burger-lines {\n  position: relative;\n  width: 18px;\n  height: 10px;\n}\n\n.line {\n  position: absolute;\n  left: 0;\n  width: 100%;\n  height: 1.5px;\n  background: currentColor;\n  transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), top 0.45s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.line-1 { top: 2px; }\n.line-2 { top: 7px; }\n\n.nav-demo-shell.is-open .line-1 {\n  top: 4.5px;\n  transform: rotate(45deg);\n}\n\n.nav-demo-shell.is-open .line-2 {\n  top: 4.5px;\n  transform: rotate(-45deg);\n}\n\n.page-backdrop {\n  height: calc(100vh - 80px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 14px;\n  color: rgba(20, 20, 19, 0.6);\n}\n\n.overlay-menu {\n  position: fixed;\n  inset: 0;\n  background: #141413;\n  color: #f4f1ea;\n  z-index: 20;\n  display: flex;\n  align-items: center;\n  padding: 0 48px;\n  clip-path: inset(0 0 100% 0);\n  transition: clip-path 0.75s cubic-bezier(0.76, 0, 0.24, 1);\n}\n\n.nav-demo-shell.is-open .overlay-menu {\n  clip-path: inset(0 0 0% 0);\n}\n\n.menu-links {\n  list-style: none;\n  width: 100%;\n}\n\n.menu-links li {\n  overflow: hidden;\n  border-bottom: 1px solid rgba(244, 241, 234, 0.12);\n}\n\n.menu-links a {\n  display: flex;\n  align-items: baseline;\n  gap: 24px;\n  padding: 18px 0;\n  color: #f4f1ea;\n  text-decoration: none;\n  font-size: clamp(2rem, 4.5vw, 3.6rem);\n  transform: translateY(100%);\n  opacity: 0;\n  transition: transform 0.65s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.65s ease, padding-left 0.3s ease;\n  transition-delay: calc(var(--i) * 75ms + 120ms);\n}\n\n.nav-demo-shell.is-open .menu-links a {\n  transform: translateY(0);\n  opacity: 1;\n}\n\n.menu-links a:hover {\n  padding-left: 18px;\n  color: #e6ccb2;\n}\n\n.menu-links a span {\n  font-size: 12px;\n  font-family: monospace;\n  opacity: 0.5;\n}\n\n.menu-links a em {\n  font-family: Georgia, serif;\n  font-style: italic;\n}\n\n</style>\n</head>\n<body>\n  <div class=\"nav-demo-shell is-open\" id=\"navShell\">\n    <header class=\"topbar\">\n      <span class=\"brand\">VIVMGMT</span>\n      <button class=\"burger-btn\" id=\"burgerBtn\" type=\"button\" aria-expanded=\"true\" aria-label=\"Toggle Menu\">\n        <span class=\"burger-label\" id=\"burgerLabel\">CLOSE</span>\n        <span class=\"burger-lines\">\n          <span class=\"line line-1\"></span>\n          <span class=\"line line-2\"></span>\n        </span>\n      </button>\n    </header>\n\n    <div class=\"page-backdrop\">\n      <p>Click the top-right trigger to toggle the staggered full-screen navigation curtain.</p>\n    </div>\n\n    <nav class=\"overlay-menu\" id=\"overlayMenu\">\n      <ul class=\"menu-links\">\n        <li style=\"--i:0\"><a href=\"#artists\"><span>01</span>Artists <em>Roster</em></a></li>\n        <li style=\"--i:1\"><a href=\"#news\"><span>02</span>Editorial <em>Chronicle</em></a></li>\n        <li style=\"--i:2\"><a href=\"#syndication\"><span>03</span>Global <em>Syndication</em></a></li>\n        <li style=\"--i:3\"><a href=\"#contact\"><span>04</span>Paris &amp; NY <em>Offices</em></a></li>\n      </ul>\n    </nav>\n  </div>\n  <script>\n(function () {\n  const shell = document.getElementById('navShell');\n  const btn = document.getElementById('burgerBtn');\n  const label = document.getElementById('burgerLabel');\n\n  function toggleMenu() {\n    const isOpen = shell.classList.toggle('is-open');\n    btn.setAttribute('aria-expanded', String(isOpen));\n    label.textContent = isOpen ? 'CLOSE' : 'MENU';\n  }\n\n  btn.addEventListener('click', toggleMenu);\n  document.querySelectorAll('.menu-links a').forEach((a) => {\n    a.addEventListener('click', (e) => {\n      e.preventDefault();\n      toggleMenu();\n    });\n  });\n})();\n\n</script>\n</body>\n</html>\n",
