      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>OKLCH Ambient Aurora Hero</title>\n  <style>\n:root {\n  --h1: 275;\n  --h2: 320;\n  --h3: 200;\n  --mx: 50%;\n  --my: 40%;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody, html {\n  width: 100%;\n  height: 100%;\n  background: #09090b;\n  color: #fafafa;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  overflow: hidden;\n}\n\n.aurora-hero {\n  position: relative;\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n  padding: 24px;\n}\n\n.aurora-orb {\n  position: absolute;\n  border-radius: 50%;\n  filter: blur(78px);\n  opacity: 0.55;\n  pointer-events: none;\n  transition: background 0.7s ease;\n  mix-blend-mode: screen;\n}\n\n.orb-1 {\n  width: 480px;\n  height: 480px;\n  left: calc(var(--mx) - 240px);\n  top: calc(var(--my) - 240px);\n  background: radial-gradient(circle, oklch(0.68 0.26 var(--h1)), transparent 70%);\n}\n\n.orb-2 {\n  width: 420px;\n  height: 420px;\n  right: 12%;\n  top: 14%;\n  background: radial-gradient(circle, oklch(0.65 0.24 var(--h2)), transparent 70%);\n  animation: floatOrb 8s ease-in-out infinite alternate;\n}\n\n.orb-3 {\n  width: 390px;\n  height: 390px;\n  left: 15%;\n  bottom: 10%;\n  background: radial-gradient(circle, oklch(0.72 0.21 var(--h3)), transparent 70%);\n  animation: floatOrb 10s ease-in-out infinite alternate-reverse;\n}\n\n@keyframes floatOrb {\n  0% { transform: translate3d(-25px, -15px, 0) scale(0.95); }\n  100% { transform: translate3d(25px, 20px, 0) scale(1.08); }\n}\n\n.hero-grid-lines {\n  position: absolute;\n  inset: 0;\n  background-image:\n    linear-gradient(to right, rgba(255,255,255,0.04) 1px, transparent 1px),\n    linear-gradient(to bottom, rgba(255,255,255,0.04) 1px, transparent 1px);\n  background-size: 48px 48px;\n  mask-image: radial-gradient(circle at center, #000 35%, transparent 80%);\n  pointer-events: none;\n}\n\n.hero-content {\n  position: relative;\n  z-index: 2;\n  text-align: center;\n  max-width: 680px;\n  animation: lpHeroIn 0.85s cubic-bezier(0.16, 1, 0.3, 1) both;\n}\n\n@keyframes lpHeroIn {\n  from {\n    opacity: 0;\n    filter: blur(12px);\n    transform: translateY(18px) scale(0.98);\n  }\n  to {\n    opacity: 1;\n    filter: blur(0);\n    transform: translateY(0) scale(1);\n  }\n}\n\n.hero-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 14px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  font-size: 11px;\n  letter-spacing: 0.14em;\n  color: #d4d4d8;\n  margin-bottom: 22px;\n}\n\n.pulse-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: oklch(0.75 0.24 var(--h1));\n  box-shadow: 0 0 12px oklch(0.75 0.24 var(--h1));\n}\n\n.hero-title {\n  font-size: clamp(2.2rem, 5vw, 4rem);\n  font-weight: 700;\n  letter-spacing: -0.04em;\n  line-height: 1.05;\n  margin-bottom: 16px;\n}\n\n.gradient-span {\n  background: linear-gradient(135deg, #ffffff 15%, oklch(0.82 0.2 var(--h1)) 55%, oklch(0.78 0.22 var(--h2)) 95%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n\n.hero-sub {\n  font-size: 15px;\n  line-height: 1.6;\n  color: #a1a1aa;\n  margin-bottom: 28px;\n}\n\n.preset-chips {\n  display: inline-flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 8px;\n}\n\n.chip {\n  background: rgba(24, 24, 27, 0.75);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  color: #e4e4e7;\n  padding: 8px 16px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.chip.is-active,\n.chip:hover {\n  background: #fafafa;\n  color: #09090b;\n  border-color: #fafafa;\n}\n\n</style>\n</head>\n<body>\n  <section class=\"aurora-hero\" id=\"auroraHero\">\n    <div class=\"aurora-orb orb-1\"></div>\n    <div class=\"aurora-orb orb-2\"></div>\n    <div class=\"aurora-orb orb-3\"></div>\n    <div class=\"hero-grid-lines\"></div>\n\n    <div class=\"hero-content\">\n      <div class=\"hero-pill\">\n        <span class=\"pulse-dot\"></span>\n        <span>21ST.DEV WIDE-GAMUT OKLCH ENGINE</span>\n      </div>\n\n      <h1 class=\"hero-title\">\n        Ship interfaces with<br />\n        <span class=\"gradient-span\">perceptual depth.</span>\n      </h1>\n\n      <p class=\"hero-sub\">\n        Interactive OKLCH radial shaders respond to cursor coordinates and chroma presets without muddying midtones.\n      </p>\n\n      <div class=\"preset-chips\" id=\"presetChips\">\n        <button class=\"chip is-active\" data-h1=\"275\" data-h2=\"320\" data-h3=\"200\">Ultraviolet</button>\n        <button class=\"chip\" data-h1=\"155\" data-h2=\"195\" data-h3=\"120\">Emerald Cyber</button>\n        <button class=\"chip\" data-h1=\"35\" data-h2=\"12\" data-h3=\"300\">Solar Flare</button>\n        <button class=\"chip\" data-h1=\"230\" data-h2=\"260\" data-h3=\"185\">Deep Cryo</button>\n      </div>\n    </div>\n  </section>\n  <script>\n(function () {\n  const root = document.documentElement;\n  const hero = document.getElementById('auroraHero');\n  const chips = document.querySelectorAll('#presetChips .chip');\n\n  hero.addEventListener('mousemove', (e) => {\n    const rect = hero.getBoundingClientRect();\n    const x = ((e.clientX - rect.left) / rect.width) * 100;\n    const y = ((e.clientY - rect.top) / rect.height) * 100;\n    root.style.setProperty('--mx', `${x.toFixed(1)}%`);\n    root.style.setProperty('--my', `${y.toFixed(1)}%`);\n  });\n\n  chips.forEach((chip) => {\n    chip.addEventListener('click', () => {\n      chips.forEach((c) => c.classList.remove('is-active'));\n      chip.classList.add('is-active');\n      root.style.setProperty('--h1', chip.getAttribute('data-h1'));\n      root.style.setProperty('--h2', chip.getAttribute('data-h2'));\n      root.style.setProperty('--h3', chip.getAttribute('data-h3'));\n    });\n  });\n})();\n\n</script>\n</body>\n</html>\n",
