      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Iridescent Liquid-Metal Shader Card</title>\n  <style>\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody, html {\n  width: 100%;\n  height: 100%;\n  background: #09090b;\n  color: #fafafa;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  overflow: hidden;\n}\n\n.shader-stage {\n  width: 100%;\n  height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  perspective: 1000px;\n}\n\n.metal-card {\n  position: relative;\n  width: 420px;\n  height: 265px;\n  border-radius: 18px;\n  overflow: hidden;\n  border: 1px solid rgba(255, 255, 255, 0.22);\n  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.65);\n  transform-style: preserve-3d;\n  transition: transform 0.15s ease-out;\n  cursor: crosshair;\n}\n\n#metalCanvas {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.metal-overlay {\n  position: relative;\n  z-index: 2;\n  height: 100%;\n  padding: 22px 24px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  background: linear-gradient(180deg, rgba(9,9,11,0.18) 0%, rgba(9,9,11,0.72) 100%);\n}\n\n.metal-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 11px;\n  font-family: monospace;\n  letter-spacing: 0.14em;\n}\n\n.metal-chip {\n  padding: 4px 10px;\n  border-radius: 999px;\n  background: rgba(9, 9, 11, 0.55);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n}\n\n.metal-bottom h2 {\n  font-size: 22px;\n  font-weight: 600;\n  letter-spacing: -0.02em;\n  margin-bottom: 4px;\n}\n\n.metal-bottom p {\n  font-size: 12px;\n  color: rgba(250, 250, 250, 0.78);\n}\n\n</style>\n</head>\n<body>\n  <div class=\"shader-stage\">\n    <div class=\"metal-card\" id=\"metalCard\">\n      <canvas id=\"metalCanvas\" width=\"360\" height=\"220\"></canvas>\n      <div class=\"metal-overlay\">\n        <div class=\"metal-top\">\n          <span class=\"metal-chip\">CHROMATIC SHADER // V2</span>\n          <span class=\"metal-id\">#0021</span>\n        </div>\n        <div class=\"metal-bottom\">\n          <h2>Liquid Chrome Surface</h2>\n          <p>Move cursor across card to bend interference fringes</p>\n        </div>\n      </div>\n    </div>\n  </div>\n  <script>\n(function () {\n  const card = document.getElementById('metalCard');\n  const canvas = document.getElementById('metalCanvas');\n  const ctx = canvas.getContext('2d');\n  const w = 120;\n  const h = 75;\n  canvas.width = w;\n  canvas.height = h;\n\n  let mx = 0.5;\n  let my = 0.5;\n  let t = 0;\n\n  card.addEventListener('mousemove', (e) => {\n    const rect = card.getBoundingClientRect();\n    mx = (e.clientX - rect.left) / rect.width;\n    my = (e.clientY - rect.top) / rect.height;\n    const rx = (0.5 - my) * 16;\n    const ry = (mx - 0.5) * 16;\n    card.style.transform = `rotateX(${rx.toFixed(2)}deg) rotateY(${ry.toFixed(2)}deg)`;\n  });\n\n  card.addEventListener('mouseleave', () => {\n    card.style.transform = 'rotateX(0deg) rotateY(0deg)';\n  });\n\n  const imgData = ctx.createImageData(w, h);\n  const data = imgData.data;\n\n  function render() {\n    t += 0.035;\n    let p = 0;\n    for (let y = 0; y < h; y++) {\n      const ny = y / h;\n      for (let x = 0; x < w; x++) {\n        const nx = x / w;\n        const dx = nx - mx;\n        const dy = ny - my;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        const wave = Math.sin(dist * 22 - t * 2.2) + Math.cos((nx * 6 + ny * 5) + t);\n        const r = 135 + Math.sin(wave * 2.1 + 0.2) * 110;\n        const g = 135 + Math.sin(wave * 2.1 + 2.1) * 110;\n        const b = 155 + Math.sin(wave * 2.1 + 4.2) * 100;\n        data[p++] = r;\n        data[p++] = g;\n        data[p++] = b;\n        data[p++] = 255;\n      }\n    }\n    ctx.putImageData(imgData, 0, 0);\n    requestAnimationFrame(render);\n  }\n  requestAnimationFrame(render);\n})();\n\n</script>\n</body>\n</html>\n",
      "html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Iridescent Liquid-Metal Shader Card</title>\n  <link rel=\"stylesheet\" href=\"style.css\" />\n</head>\n<body>\n  <div class=\"shader-stage\">\n    <div class=\"metal-card\" id=\"metalCard\">\n      <canvas id=\"metalCanvas\" width=\"360\" height=\"220\"></canvas>\n      <div class=\"metal-overlay\">\n        <div class=\"metal-top\">\n          <span class=\"metal-chip\">CHROMATIC SHADER // V2</span>\n          <span class=\"metal-id\">#0021</span>\n        </div>\n        <div class=\"metal-bottom\">\n          <h2>Liquid Chrome Surface</h2>\n          <p>Move cursor across card to bend interference fringes</p>\n        </div>\n      </div>\n    </div>\n  </div>\n  <script src=\"script.js\"></script>\n</body>\n</html>\n",
