      "combined": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Kinetic Editorial Strapline Scrub</title>\n  <style>\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody, html {\n  width: 100%;\n  height: 100%;\n  background: #0b0b0e;\n  color: #f4f4f6;\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;\n  overflow: hidden;\n}\n\n.strapline-stage {\n  height: 100vh;\n  max-width: 920px;\n  margin: 0 auto;\n  padding: 32px 36px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n}\n\n.strapline-meta {\n  display: flex;\n  justify-content: space-between;\n  font-size: 11px;\n  font-family: monospace;\n  letter-spacing: 0.16em;\n  color: #71717a;\n}\n\n.strapline-copy {\n  font-size: clamp(1.75rem, 3.8vw, 3.1rem);\n  line-height: 1.22;\n  letter-spacing: -0.03em;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.28em;\n}\n\n.k-word {\n  transition: color 0.2s ease, opacity 0.2s ease, transform 0.25s ease;\n  opacity: 0.18;\n  transform: translateY(4px);\n}\n\n.k-word.is-serif {\n  font-family: Georgia, 'Times New Roman', serif;\n  font-style: italic;\n  font-weight: 400;\n}\n\n.k-word.is-lit {\n  opacity: 1;\n  color: #fafafa;\n  transform: translateY(0);\n}\n\n.k-word.is-lit.is-serif {\n  color: #d8b4fe;\n}\n\n.strapline-controls {\n  display: flex;\n  align-items: center;\n}\n\n#wordScrubber {\n  width: 100%;\n  accent-color: #a855f7;\n  cursor: pointer;\n}\n\n</style>\n</head>\n<body>\n  <section class=\"strapline-stage\">\n    <div class=\"strapline-meta\">\n      <span>KINETIC MANIFESTO // SCROLL WHEEL OR DRAG SLIDER</span>\n      <span id=\"progressReadout\">68%</span>\n    </div>\n\n    <p class=\"strapline-copy\" id=\"straplineCopy\"></p>\n\n    <div class=\"strapline-controls\">\n      <input type=\"range\" id=\"wordScrubber\" min=\"0\" max=\"100\" value=\"68\" aria-label=\"Word reveal progress\" />\n    </div>\n  </section>\n  <script>\n(function () {\n  const TOKENS = [\n    { t: 'We', s: false }, { t: 'extract', s: false }, { t: 'tactile', s: true },\n    { t: 'motion,', s: true }, { t: '3D', s: false }, { t: 'spatial', s: false },\n    { t: 'carousels,', s: true }, { t: 'and', s: false }, { t: 'wide-gamut', s: false },\n    { t: 'shaders', s: true }, { t: 'into', s: false }, { t: 'zero-dependency', s: false },\n    { t: 'building', s: false }, { t: 'blocks', s: true }, { t: 'ready', s: false },\n    { t: 'for', s: false }, { t: 'instant', s: true }, { t: 'production', s: false },\n    { t: 'shipping.', s: true }\n  ];\n\n  const copyEl = document.getElementById('straplineCopy');\n  const scrubber = document.getElementById('wordScrubber');\n  const readout = document.getElementById('progressReadout');\n\n  const spans = TOKENS.map((item) => {\n    const span = document.createElement('span');\n    span.className = 'k-word' + (item.s ? ' is-serif' : '');\n    span.textContent = item.t;\n    copyEl.appendChild(span);\n    return span;\n  });\n\n  function updateProgress(pct) {\n    const clamped = Math.max(0, Math.min(100, Number(pct)));\n    scrubber.value = String(Math.round(clamped));\n    readout.textContent = `${Math.round(clamped)}%`;\n    const activeCount = Math.round((clamped / 100) * spans.length);\n    spans.forEach((s, idx) => {\n      s.classList.toggle('is-lit', idx < activeCount);\n    });\n  }\n\n  scrubber.addEventListener('input', (e) => updateProgress(e.target.value));\n  window.addEventListener('wheel', (e) => {\n    const next = Number(scrubber.value) + (e.deltaY > 0 ? 6 : -6);\n    updateProgress(next);\n  }, { passive: true });\n\n  updateProgress(68);\n})();\n\n</script>\n</body>\n</html>\n",
